{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Surveillance Data",
    "url": "http://localhost:7807",
    "widgets_json": {
      "policy_digest_pdf": {
        "name": "Policy Digest PDF",
        "description": "Current surveillance policy digest.",
        "endpoint": "/policy-digest-pdf",
        "type": "pdf",
        "w": 16,
        "h": 14,
        "category": "Surveillance",
        "source": "/policy/digest.pdf",
        "staleTime": 900000,
        "params": [
          {
            "paramName": "case_scope",
            "type": "text",
            "label": "Case scope",
            "value": "C-1042",
            "description": "Case bundle for the policy review."
          }
        ]
      },
      "alert_queue": {
        "name": "Alert Queue",
        "description": "Open surveillance alerts.",
        "endpoint": "/alert-queue",
        "type": "table",
        "w": 20,
        "h": 9,
        "staleTime": 900000,
        "params": [
          {
            "paramName": "severity",
            "type": "text",
            "label": "Severity",
            "value": "high",
            "options": [
              { "value": "high", "label": "High" },
              { "value": "medium", "label": "Medium" },
              { "value": "low", "label": "Low" }
            ]
          }
        ],
        "data": {
          "columnsDefs": [
            { "field": "alert_id", "headerName": "Alert", "cellDataType": "text" },
            { "field": "desk", "headerName": "Desk", "cellDataType": "text" },
            { "field": "severity", "headerName": "Severity", "cellDataType": "text", "renderFn": "titleCase" },
            { "field": "age_days", "headerName": "Age (d)", "cellDataType": "number", "formatterFn": "int" }
          ]
        }
      },
      "case_notes": {
        "name": "Case Notes",
        "description": "Notes for one surveillance case.",
        "endpoint": "/case-notes",
        "type": "markdown",
        "w": 12,
        "h": 8,
        "staleTime": 900000,
        "params": [
          {
            "paramName": "case_id",
            "type": "text",
            "label": "Case",
            "value": "C-1042",
            "description": "Case identifier."
          }
        ]
      }
    }
  }
}

